// Auto detekcja przewoznika po formacie numeru listu przewozowego.
const raw = ($json.tracking_number || '').replace(/\s+/g, '');
if (!raw) return [{ json: { error: 'empty_tracking' } }];

let carrier = 'unknown';

// InPost: 24 cyfry albo 12-14 cyfr zaczynajace sie od 6
if (/^6\d{11,23}$/.test(raw)) carrier = 'inpost';
// DPD: 14 cyfr zaczynajace sie od 0 lub 5
else if (/^[05]\d{13}$/.test(raw)) carrier = 'dpd';
// DHL: 10 cyfr
else if (/^\d{10}$/.test(raw)) carrier = 'dhl';
// Poczta Polska: 20 znakow, kombinacja liter i cyfr, konczy sie na PL
else if (/^[A-Z]{2}\d{9}PL$/i.test(raw)) carrier = 'poczta';
// FedEx: 12 cyfr
else if (/^\d{12}$/.test(raw)) carrier = 'fedex';
// UPS: 1Z + 16 znakow
else if (/^1Z[A-Z0-9]{16}$/i.test(raw)) carrier = 'ups';

return [{ json: { tracking_number: raw, carrier } }];

// Normalizacja odpowiedzi kuriera do wspolnego formatu wewnetrznego.
const carrier = $node['Detect Carrier'].json.carrier;
const raw = $json;

let normalized = {
  tracking_number: $node['Detect Carrier'].json.tracking_number,
  carrier,
  status: 'unknown',
  status_readable: null,
  last_scan_datetime: null,
  last_scan_location: null,
  estimated_delivery: null,
  history: []
};

if (carrier === 'inpost') {
  const history = raw.tracking_details || raw.status_history || [];
  normalized.status = raw.status || 'unknown';
  normalized.status_readable = raw.status;
  normalized.last_scan_datetime = history[0]?.datetime;
  normalized.last_scan_location = history[0]?.origin_status?.name;
  normalized.estimated_delivery = raw.expected_delivery_date;
  normalized.history = history.slice(0, 5).map(h => ({ ts: h.datetime, status: h.status, location: h.origin_status?.name }));
} else if (carrier === 'dpd') {
  const events = raw.events || [];
  normalized.status = raw.status || 'unknown';
  normalized.last_scan_datetime = events[0]?.date;
  normalized.last_scan_location = events[0]?.location;
  normalized.history = events.slice(0, 5).map(e => ({ ts: e.date, status: e.description, location: e.location }));
} else if (carrier === 'dhl') {
  const s = raw.shipments?.[0];
  const events = s?.events || [];
  normalized.status = s?.status?.status || 'unknown';
  normalized.last_scan_datetime = events[0]?.timestamp;
  normalized.last_scan_location = events[0]?.location?.address?.addressLocality;
  normalized.estimated_delivery = s?.estimatedTimeOfDelivery;
  normalized.history = events.slice(0, 5).map(e => ({ ts: e.timestamp, status: e.description, location: e.location?.address?.addressLocality }));
} else if (carrier === 'poczta') {
  const items = raw.items || [];
  normalized.status = items[items.length-1]?.status || 'unknown';
  normalized.last_scan_datetime = items[items.length-1]?.date;
  normalized.last_scan_location = items[items.length-1]?.location;
  normalized.history = items.slice(-5).reverse().map(i => ({ ts: i.date, status: i.status, location: i.location }));
}

return [{ json: normalized }];
